import json
import os
import sys
from datetime import datetime, timezone
from typing import Optional

AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
CACHE_DIR = os.path.join(AHCLAUDE_DIR, "cache")
CONFIG_FILE = os.path.join(CACHE_DIR, "claude_config.json5")
SETTINGS_FILE = os.path.expanduser("~/.claude/settings.json")
STARTUP_LOG_FILE = os.path.join(AHCLAUDE_DIR, "startup.json")


def get_cached_api_key() -> Optional[str]:
    if not os.path.exists(CONFIG_FILE):
        return None
    try:
        import json5
        with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
            config = json5.load(f)
        return config.get("api_key")
    except Exception:
        return None


def get_cached_model_name() -> Optional[str]:
    if not os.path.exists(SETTINGS_FILE):
        return None
    try:
        with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
            settings = json.load(f)
        env = settings.get("env", {})
        return (
            env.get("ANTHROPIC_DEFAULT_SONNET_MODEL") or
            env.get("ANTHROPIC_DEFAULT_OPUS_MODEL") or
            env.get("ANTHROPIC_MODEL") or
            env.get("ANTHROPIC_DEFAULT_HAIKU_MODEL")
        )
    except Exception:
        return None


def report_activation() -> bool:
    api_key = get_cached_api_key()
    model_name = get_cached_model_name()

    if not api_key or not model_name:
        return False

    activation_data = {
        "key": api_key[:10] + "..." if len(api_key) > 10 else api_key,
        "model_name": model_name,
        "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    }

    log_file = os.path.join(AHCLAUDE_DIR, "activation.log")
    os.makedirs(AHCLAUDE_DIR, exist_ok=True)
    with open(log_file, 'a', encoding='utf-8') as f:
        f.write(f"[activation] {json.dumps(activation_data, ensure_ascii=False)}\n")

    return True


def handle_start(session_id=None, working_directory=None, emit_output=True):
    # hook 绝对不能以非 0 退出，否则会中断会话
    try:
        _do_handle_start(session_id, working_directory, emit_output)
    except Exception:
        pass


def _do_handle_start(session_id=None, working_directory=None, emit_output=True):
    from ahclaude_plugin.hook.logger import hook_log

    input_data = {}
    if not session_id:
        try:
            raw = sys.stdin.buffer.read()
            input_data = json.loads(raw.decode('utf-8'))
            session_id = input_data.get("session_id", "")
            working_directory = input_data.get("cwd") or input_data.get("working_directory") or working_directory or os.getcwd()
        except Exception as e:
            hook_log("error", f"cmd_start JSON解析失败: {e}")
            pass

    if not session_id:
        return

    # 先激活 key，确保在任何耗时操作之前完成激活
    try:
        from ahclaude_plugin.hook.cmd_prompt import activate_token_with_log
        auth_data = {}
        if os.path.exists(os.path.expanduser("~/.ahdev/auth.json")):
            import json as _json
            with open(os.path.expanduser("~/.ahdev/auth.json"), "r", encoding="utf-8") as _f:
                auth_data = _json.load(_f)
        token = auth_data.get("token", auth_data.get("api_key", ""))
        if token:
            from ahclaude_plugin.hook.codex_auth import ensure_codex_apikey_auth
            if ensure_codex_apikey_auth(token):
                hook_log("auth", "已修复 Codex auth.json 为 apikey 模式，清理 ChatGPT tokens", session_id=session_id)
            activate_token_with_log(token, source="SessionStart")
    except Exception as e:
        hook_log("error", f"cmd_start activate失败: {e}")

    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    os.makedirs(AHCLAUDE_DIR, exist_ok=True)

    startup_data = {
        "sessions": [],
        "last_updated": timestamp
    }

    if os.path.exists(STARTUP_LOG_FILE):
        try:
            with open(STARTUP_LOG_FILE, 'r', encoding='utf-8') as f:
                startup_data = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            hook_log("error", f"cmd_start 读取startup文件失败: {e}")

    new_record = {
        "session_id": session_id,
        "working_directory": working_directory or os.getcwd(),
        "start_time": timestamp,
        "end_time": None,
        "status": "active"
    }

    session_exists = False
    for record in startup_data.get("sessions", []):
        if record.get("session_id") == session_id:
            record["start_time"] = timestamp
            record["working_directory"] = working_directory or os.getcwd()
            record["status"] = "active"
            record["end_time"] = None
            session_exists = True
            break

    if not session_exists:
        startup_data["sessions"].append(new_record)

    if len(startup_data["sessions"]) > 100:
        startup_data["sessions"] = startup_data["sessions"][-100:]

    startup_data["last_updated"] = timestamp

    try:
        with open(STARTUP_LOG_FILE, 'w', encoding='utf-8') as f:
            json.dump(startup_data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        hook_log("error", f"cmd_start 写入startup文件失败: {e}")

    try:
        from ahclaude_plugin.hook.logger import hook_log_raw
        from ahclaude_plugin.session_cache import init_session

        hook_log("start", f"dir={working_directory or os.getcwd()}", session_id=session_id)
        hook_log_raw("start", input_data)
        init_session(session_id)
    except Exception as e:
        hook_log("error", f"cmd_start logger/session_cache操作失败: {e}")

    if emit_output == "codex":
        print(json.dumps({
            "hookSpecificOutput": {
                "hookEventName": "SessionStart",
                "additionalContext": ""
            }
        }))
    elif emit_output:
        print(f"启动记录已保存: session={session_id[:8]}... dir={working_directory or os.getcwd()}")


MOCK_START_INPUT = {
    "session_id": "test-session-123",
    "transcript_path": "/Users/test/.claude/projects/test/test.jsonl",
    "cwd": "/Users/test/project",
    "hook_event_name": "SessionStart",
    "source": "startup",
    "model": "claude-sonnet-4-6"
}


def test_main():
    print("Running with mock data...")
    input_data = MOCK_START_INPUT
    print(f"DEBUG start input: {json.dumps(input_data, ensure_ascii=False)}", file=sys.stderr)

    from ahclaude_plugin.hook.logger import hook_log_raw
    hook_log_raw("start", input_data)

    print(f"Test completed. Check log file: ~/.ahdev/hook-{datetime.now().strftime('%Y-%m-%d')}.log")


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--test":
        test_main()
    else:
        handle_start()
